input.command:
mkdir -p src/emails && 
cat > .env.example <<'EOF'
RESEND_API_KEY=re_placeholder
RESEND_FROM_EMAIL=onboarding@resend.dev
APP_URL=http://localhost:3000
EOF
printf '!.env.example\n' >> .gitignore
cat > src/lib/resend.ts <<'EOF'
import { Resend } from "resend";

let client: Resend | undefined;

export function getResend(): Resend {
  const key = process.env.RESEND_API_KEY;
  if (!key) throw new Error("RESEND_API_KEY is not set");
  return (client ??= new Resend(key));
}
EOF
cat > src/emails/welcome.tsx <<'EOF'
export function WelcomeEmail({ name, appUrl }: { name: string; appUrl: string }) {
  return (
    <div>
      <h1>Welcome to Notely, {name}!</h1>
      <p>Your account is ready. Start taking notes any time:</p>
      <p>
        <a href={`${appUrl}/dashboard`}>Open your dashboard</a>
      </p>
    </div>
  );
}
EOF
cat > src/emails/password-reset.tsx <<'EOF'
export function PasswordResetEmail({ name, actionUrl }: { name: string; actionUrl: string }) {
  return (
    <div>
      <h1>Reset your password</h1>
      <p>Hi {name}, we received a request to reset your Notely password.</p>
      <p>
        <a href={actionUrl}>Choose a new password</a>
      </p>
      <p>This link expires in 1 hour. If you didn&apos;t request it, you can ignore this email.</p>
    </div>
  );
}
EOF
cat > src/lib/email.ts <<'EOF'
import type { ReactElement } from "react";
import { getResend } from "@/lib/resend";
import { WelcomeEmail } from "@/emails/welcome";
import { PasswordResetEmail } from "@/emails/password-reset";

const appUrl = () => process.env.APP_URL ?? "http://localhost:3000";

// Resend resolves to { error } instead of throwing; a failed email must not break the caller.
async function send(to: string, subject: string, react: ReactElement) {
  try {
    const { error } = await getResend().emails.send({
      from: process.env.RESEND_FROM_EMAIL ?? "onboarding@resend.dev",
      to,
      subject,
      react,
    });
    if (error) console.error(`Email "${subject}" failed: ${error.name}: ${error.message}`);
  } catch (e) {
    console.error(`Email "${subject}" failed:`, e);
  }
}

export function sendWelcomeEmail(user: { email: string; name: string }) {
  return send(user.email, "Welcome to Notely", WelcomeEmail({ name: user.name, appUrl: appUrl() }));
}

export function sendPasswordResetEmail(user: { email: string; name: string }, token: string) {
  const actionUrl = `${appUrl()}/reset-password?token=${encodeURIComponent(token)}`;
  return send(user.email, "Reset your Notely password", PasswordResetEmail({ name: user.name, actionUrl }));
}
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email === email)) throw new Error("Email already registered");
  const user: User = {
    id: String(users.length + 1),
    email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

// TODO: tokens live in memory only; persist the hash and verify it in the reset route once there is a DB.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

// Silently does nothing for unknown emails so callers can't probe which addresses are registered.
export async function requestPasswordReset(email: string): Promise<void> {
  const normalized = email.trim().toLowerCase();
  const user = users.find((u) => u.email === normalized);
  if (!user) return;
  const token = randomBytes(32).toString("hex");
  resetTokens.set(createHash("sha256").update(token).digest("hex"), {
    userId: user.id,
    expiresAt: Date.now() + 60 * 60 * 1000,
  });
  await sendPasswordResetEmail(user, token);
}
EOF
